import * as M from './model.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(M.KEY));if(state?.v!==3)state=M.initial();}catch{state=M.initial();}
let view=location.hash.slice(1)||'home',q=0,draft=[],examLang='en',uploadError='',uploadFail=false,queueQuery='',queueStatus='all',profileId='Ahmed',selectedResult=null;
const t=(en,de)=>state.lang==='de'?de:en;const app=$('#app');const modal=$('#modal');let processTimer;let fileDB;
const icons={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',upload:'M12 16V3m-5 5 5-5 5 5 M4 15v6h16v-6',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3Z M12 6v16',chart:'M4 20V11m8 9V4m8 16v-7 M2 21h20',bell:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5Z M10 21h4',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',file:'M5 2h9l5 5v15H5Z M14 2v6h5 M8 12h8m-8 4h6',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8m2 3a4 4 0 0 1 3 4v3',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',support:'M12 3a7 7 0 0 0-4 13v4h8v-4a7 7 0 0 0-4-13Z M9 23h6 M12 6v4',edit:'m4 16-1 5 5-1L21 7l-4-4Z M14 6l4 4',lock:'M6 10V7a6 6 0 0 1 12 0v3 M4 10h16v12H4Z M12 14v4',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6m0-10v1',close:'m6 6 12 12M6 18 18 6',leaf:'M4 20C1 3 12 1 21 3c1 14-9 20-17 17ZM5 19 17 7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',download:'M12 3v13m-5-5 5 5 5-5 M4 18v4h16v-4',reset:'M3 11a9 9 0 1 1 2 7 M3 4v7h7',mail:'M3 5h18v14H3Z m0 0 9 8 9-8'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;}
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const pill=(text,cls='')=>`<span class="pill ${cls}">${text}</span>`;
const alert=(text,cls='info')=>`<div class="alert ${cls}">${icon('info')}<div>${text}</div></div>`;
function save(){try{localStorage.setItem(M.KEY,JSON.stringify(state));}catch{toast(t('Storage is full. Keep this tab open; changes may not survive a reload.','Speicher voll. Bitte diesen Tab offen lassen.'));}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function go(v){view=v;location.hash=v;render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});}
function heading(title,sub,action='',label=''){return `<div class="heading"><div>${label?`<div class="eyebrow">${label}</div>`:''}<h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const brand=()=>`<div class="brand"><span class="brandmark">${icon('book')}</span>LearningBridge</div>`;
function art(){return `<svg viewBox="0 0 280 230" fill="none" aria-hidden="true"><ellipse cx="140" cy="202" rx="110" ry="17" fill="#cad9bc"/><rect x="63" y="31" width="157" height="165" rx="12" fill="#b6cda4" transform="rotate(9 63 31)"/><rect x="46" y="18" width="157" height="176" rx="10" fill="#fffef7" stroke="#c7d4bb"/><path d="M67 49h71M67 61h111" stroke="#bcc9b4" stroke-width="5" stroke-linecap="round"/><rect x="68" y="86" width="112" height="28" rx="5" fill="#e9efdd"/><rect x="68" y="86" width="37" height="28" rx="5" fill="#90b57a"/><path d="M105 87v26m37-26v26" stroke="#c1d1b4"/><rect x="68" y="129" width="112" height="28" rx="5" fill="#e9efdd"/><rect x="68" y="129" width="28" height="28" rx="5" fill="#c8a96b"/><path d="M96 130v26m28-26v26m28-26v26" stroke="#c1d1b4"/><circle cx="210" cy="151" r="32" fill="#2d624e"/><path d="m195 151 10 10 21-23" stroke="white" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="m24 117-7 8m8-39-9-4m218-32 9-7m-5 45 12 2" stroke="#8da57b" stroke-width="3" stroke-linecap="round"/></svg>`;}
const names={home:['Home','Start'],upload:['Upload exam','Prüfung senden'],results:['My results','Ergebnisse'],progress:['My progress','Fortschritt'],messages:['Messages','Nachrichten'],dashboard:['Class overview','Klassenübersicht'],queue:['Review queue','Prüfungen'],support:['Learning support','Lernhilfe'],students:['Student progress','Lernfortschritt'],activity:['Review history','Verlauf']};
const navicons={home:'home',upload:'upload',results:'book',progress:'chart',messages:'bell',dashboard:'home',queue:'file',support:'support',students:'users',activity:'clock'};
function nav(){const keys=state.role==='student'?['home','upload','results','progress','messages']:['dashboard','queue','support','students','activity'];return keys.map(k=>`<button data-action="nav" data-view="${k}" class="${view===k?'active':''}" ${view===k?'aria-current="page"':''}>${icon(navicons[k])}<span>${t(...names[k])}</span>${k==='messages'&&state.notifications.some(n=>!n.read)?`<span class="nav-badge">${state.notifications.filter(n=>!n.read).length}</span>`:''}</button>`).join('');}
function demoToolbar(){return `<div class="demo-toolbar"><button data-action="guide">${t('Demo guide','Demo-Anleitung')}</button><button data-action="reset">${t('Reset demo','Demo zurücksetzen')}</button></div>`;}
function entry(){return `<div class="entry"><section class="entry-story">${brand()}<h1>${t('Every answer.<br>A clearer next step.','Jede Antwort.<br>Ein klarer nächster Schritt.')}</h1><p>${t('A little understanding goes a long way. Turn checked exam answers into thoughtful feedback and purposeful practice.','Aus geprüften Antworten werden hilfreiches Feedback und passende Übungen.')}</p><div class="entry-art">${art()}</div><footer>AL AHLY &nbsp; / &nbsp; CSEN 909 &nbsp; / &nbsp; MILESTONE 3</footer></section><main class="entry-form" id="main" tabindex="-1"><div class="label">${t('WELCOME TO LEARNINGBRIDGE','WILLKOMMEN BEI LEARNINGBRIDGE')}</div><h2>${t('Let’s get started.','Los geht’s.')}</h2><p>${t('Choose a space to explore. Your work stays with you when you switch roles.','Wähle eine Ansicht. Deine Arbeit bleibt beim Wechsel erhalten.')}</p><button class="role-card" data-action="role" data-role="student"><span class="icon-tile">${icon('book')}</span><div><h3>${t('I’m a student','Ich bin Schüler/in')}</h3><p>Ahmed · ${t('Grade 4','Klasse 4')}</p></div><span class="arrow">${icon('arrow')}</span></button><button class="role-card teacher" data-action="role" data-role="teacher"><span class="icon-tile">${icon('users')}</span><div><h3>${t('I’m a teacher','Ich bin Lehrkraft')}</h3><p>Reem Ayman · ${t('Assessment & support','Bewertung & Lernhilfe')}</p></div><span class="arrow">${icon('arrow')}</span></button><div class="actions"><label class="sr-only" for="language">Language</label><select id="language" class="language" style="width:auto"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="de" ${state.lang==='de'?'selected':''}>Deutsch</option></select>${demoToolbar()}</div><p class="prototype-note">${t('Interactive course prototype · Fictional records · Simulated OCR and AI suggestions. No password needed. This is a shared-device demonstration, not a secure school account.','Interaktiver Kursprototyp · Beispieldaten · Simulierte OCR und KI. Kein Passwort nötig. Keine echte Schul-Anmeldung.')}</p></main></div>`;}
function shell(content){return `<div class="app-shell"><aside class="sidebar">${brand()}<div class="nav-label">${state.role==='student'?t('MY LEARNING SPACE','MEIN LERNRAUM'):t('TEACHER WORKSPACE','LEHRERBEREICH')}</div><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom"><span class="plant">${icon('leaf')}</span><h3>${t('Small steps.<br>Lasting understanding.','Kleine Schritte.<br>Großes Verständnis.')}</h3><p>${t('A clear next step for every child.','Ein klarer nächster Schritt für jedes Kind.')}</p>${demoToolbar()}</div></aside><div><header class="topbar"><div class="crumb">LearningBridge <span style="margin:0 10px;color:#b4c1b5">/</span> ${t('Mathematics · Grade 4','Mathematik · Klasse 4')}</div><div class="top-actions"><label for="language" class="sr-only">Language</label><select class="language" id="language" style="width:auto"><option value="en" ${state.lang==='en'?'selected':''}>EN · English</option><option value="de" ${state.lang==='de'?'selected':''}>DE · Deutsch</option></select><button class="role-switch" data-action="switch"><span class="avatar">${state.role==='student'?'A':'R'}</span><span><strong>${state.role==='student'?'Ahmed':'Reem Ayman'}</strong><small>${t('Switch demo role','Demo-Ansicht wechseln')}</small></span></button></div></header><div class="mobile-nav" role="navigation" aria-label="Mobile navigation">${nav()}</div><main id="main" class="main" tabindex="-1">${content}<div class="status-note">${t('Course prototype · Local demo data · OCR, grades and analysis are simulated.','Kursprototyp · Lokale Beispieldaten · OCR, Noten und Analyse sind simuliert.')}</div></main></div></div>`;}
const statusText=s=>({scanning:t('Reading your pages','Seiten werden gelesen'),verify:t('Waiting for teacher check','Warten auf Prüfung'),replacement:t('Clearer page needed','Deutlichere Seite nötig'),grading:t('Preparing suggested marks','Notenvorschläge entstehen'),grade:t('Waiting for grade approval','Warten auf Notenfreigabe'),support:t('Waiting for feedback approval','Warten auf Feedback'),published:t('Results ready','Ergebnis bereit')}[s]||s);
function allResults(){return [...state.history,...(M.visibleResult(state)?[{...state.active,score:M.total(state.active),max:10}]:[])];}
function resultTable(){return `<div class="table-wrap student-results"><table aria-label="Exam results"><thead><tr><th>${t('Exam','Prüfung')}</th><th>${t('Result','Ergebnis')}</th><th>${t('Status','Status')}</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${[...allResults()].reverse().map(r=>`<tr><td><div class="exam-cell"><span class="exam-icon">${icon('file')}</span><div><strong>${esc(r.name)}</strong><small>${t('Mathematics','Mathematik')} · ${new Date(r.date).toLocaleDateString(state.lang==='de'?'de-DE':'en-GB',{day:'numeric',month:'short'})}</small></div></div></td><td><span class="score">${r.score}<small style="display:inline"> / ${r.max}</small></span></td><td>${pill(t('Teacher-approved','Freigegeben'))}</td><td>${btn(t('View result','Ansehen'),'result','ghost',`data-id="${r.id}"`)}</td></tr>`).join('')}${state.active&&state.active.status!=='published'?`<tr><td><strong>${esc(state.active.name)}</strong><small>${t('Your latest exam','Deine letzte Prüfung')}</small></td><td>—</td><td>${pill(statusText(state.active.status),'pending')}</td><td>${btn(t('Check status','Status ansehen'),'status','ghost')}</td></tr>`:''}</tbody></table></div>`;}
function progressBars(){const published=M.visibleResult(state);const marks=published?published.marks:[2,1,3];return M.rubric.map((r,i)=>`<div class="progress-row"><div class="labels"><span>${topic(i)}</span><strong>${marks[i]} / ${r.max}</strong></div><div class="bar"><span class="${i===1?'amber':''}" style="width:${marks[i]/r.max*100}%"></span></div></div>`).join('');}
const topic=i=>state.lang==='de'?['Gleichwertige Brüche','Brüche vergleichen','Bruch-Sachaufgabe'][i]:M.rubric[i].topic;
function studentHome(){const pending=state.active&&state.active.status!=='published';return heading(t('A little progress, every day.','Jeden Tag ein kleiner Schritt.'),t('Welcome back, Ahmed. What will you learn today?','Willkommen zurück, Ahmed. Was lernst du heute?'),'','AHMED’S LEARNING JOURNEY')+`<div class="grid main-aside"><div><section class="hero"><div><div class="eyebrow">${t('YOUR NEXT STEP','DEIN NÄCHSTER SCHRITT')}</div><h2>${pending?t('Your exam is on its way.','Deine Prüfung ist unterwegs.'):t('Ready to share your work?','Bereit, deine Arbeit zu zeigen?')}</h2><p>${pending?t('Your teacher will check your answers before you see your result.','Deine Lehrkraft prüft deine Antworten vor dem Ergebnis.'):t('Send your exam pages to your teacher. We’ll take it one step at a time.','Sende deine Prüfungsseiten. Wir gehen Schritt für Schritt vor.')}</p>${btn(`${icon(pending?'clock':'upload')} ${pending?t('Check my exam','Prüfung ansehen'):t('Upload my exam','Prüfung senden')}`,pending?'status':'upload')}</div><div class="hero-art">${art()}</div></section><div class="section-head"><h2>${t('Your recent exams','Deine letzten Prüfungen')}</h2>${btn(t('See all','Alle ansehen'),'nav','ghost','data-view="results"')}</div><section class="card">${resultTable()}</section></div><aside class="grid" style="align-content:start"><section class="card"><div class="actions mb"><span class="icon-tile">${icon('chart')}</span><h3>${t('Growing your skills','Deine Fähigkeiten wachsen')}</h3></div>${progressBars()}<div class="mini-note"><p class="small">${t('Compare your own steps. Every bit of understanding counts.','Vergleiche deine eigenen Schritte. Jeder Fortschritt zählt.')}</p></div></section><section class="card feedback-card"><div class="eyebrow">${t('FROM YOUR TEACHER','VON DEINER LEHRKRAFT')}</div><h3>${M.visibleResult(state)?t('Your next practice is ready.','Deine nächste Übung ist da.'):t('Let’s keep learning.','Wir lernen weiter.')}</h3><p class="small">${t('Read your feedback and ask for help whenever you need it.','Lies dein Feedback und frage, wenn du Hilfe brauchst.')}</p>${btn(t('Open messages','Nachrichten öffnen'),'nav','ghost','data-view="messages"')}</section></aside></div>`;}
function stepper(stage){return `<ol class="stepper">${[t('Add pages','Seiten wählen'),t('Teacher checks','Lehrkraft prüft'),t('Your result','Dein Ergebnis')].map((s,i)=>`<li class="${i===stage?'current':i<stage?'done':''}"><span>${i<stage?'✓':i+1}</span>${s}</li>`).join('')}</ol>`;}
function upload(){const e=state.active;const replacement=e?.status==='replacement';if(e&&e.status!=='published'&&!replacement)return status();return heading(replacement?t('Let’s try a clearer page.','Eine deutlichere Seite.'):t('Share your exam.','Sende deine Prüfung.'),t('A clear photo helps your teacher see all your good work.','Ein klares Foto hilft deiner Lehrkraft, alles zu sehen.'))+stepper(0)+`<div class="grid main-aside"><section class="card"><div class="grid two"><div class="field"><label for="exam">${t('Exam','Prüfung')}</label><select id="exam"><option>${t('Fractions 2 · Mathematics','Brüche 2 · Mathematik')}</option></select></div><div class="field"><label for="exam-language">${t('Language on your exam','Sprache der Prüfung')}</label><select id="exam-language" ${replacement?'disabled':''}><option value="en" ${examLang==='en'?'selected':''}>English</option><option value="de" ${examLang==='de'?'selected':''}>Deutsch</option></select></div></div>${replacement?alert(esc(e.requestReason),'error'):''}<div class="dropzone" id="dropzone"><span class="icon-tile">${icon('upload')}</span><h3>${t('Choose your exam pages','Wähle deine Prüfungsseiten')}</h3><p>${t('Drop files here, or choose them below.','Dateien hier ablegen oder unten auswählen.')}</p><input aria-label="${t('Choose exam files','Prüfungsdateien wählen')}" class="upload-input" type="file" id="files" multiple accept="image/png,image/jpeg,application/pdf"><label for="camera" class="text-link">${t('Or take a photo on your device','Oder fotografiere mit deinem Gerät')}</label><input id="camera" class="sr-only" type="file" accept="image/jpeg,image/png" capture="environment"><div class="help">PNG, JPG, PDF · ${t('up to 5 MB each · 4 files maximum','bis 5 MB pro Datei · höchstens 4 Dateien')}</div></div><div class="section-head"><h3>${t('Your pages','Deine Seiten')} <span id="file-count">(${draft.length})</span></h3>${btn(t('Use a sample exam','Beispielprüfung nutzen'),'sample','ghost')}</div>${draft.length?draft.map((f,i)=>`<div class="file-tile"><span class="exam-icon">${icon('file')}</span><div><strong>${esc(f.name)}</strong><small class="help">${(f.size/1024).toFixed(0)} KB · ${i+1}/${draft.length}</small></div><div class="actions">${btn(t('Preview','Vorschau'),'preview-draft','secondary small',`data-index="${i}"`)}${btn(t('Remove','Entfernen'),'remove-file','ghost small',`data-index="${i}"`)}${i?btn('↑','move-file','secondary small',`data-index="${i}" aria-label="Move page up"`):''}</div></div>`).join(''):`<p class="small">${t('No pages yet. Add your own file or use the sample for the demo.','Noch keine Seiten. Nutze eigene Dateien oder das Beispiel.')}</p>`}${uploadError?`<div role="alert">${alert(esc(uploadError),'error')}</div>`:''}<label class="check"><input type="checkbox" id="readable">${t('I checked that all pages are clear and in the right order.','Ich habe Lesbarkeit und Reihenfolge geprüft.')}</label><div class="review-controls"><span class="help">${t('Your pages stay here if sending fails.','Bei einem Fehler bleiben deine Seiten erhalten.')}</span>${btn(`${t('Send exam','Prüfung senden')} ${icon('arrow')}`,'send')}</div></section><aside><section class="card subtle"><h3>${t('A good photo in 3 steps','Ein gutes Foto in 3 Schritten')}</h3><ol style="padding-left:20px;color:var(--muted);font-size:14px;line-height:2"><li>${t('Lay your page flat in good light.','Lege das Blatt flach ins Licht.')}</li><li>${t('Keep every corner in the picture.','Alle Ecken sollen sichtbar sein.')}</li><li>${t('Read it once before sending.','Prüfe die Lesbarkeit.')}</li></ol><p class="small">${t('You can ask an adult to help.','Du kannst einen Erwachsenen um Hilfe bitten.')}</p></section><details><summary>${t('Demonstration options','Demo-Optionen')}</summary><label class="check"><input type="checkbox" id="fail-upload" ${uploadFail?'checked':''}>${t('Simulate a connection failure on the next send','Verbindungsfehler beim nächsten Senden simulieren')}</label><p class="help">${t('This demo uses a fixed fractions rubric, including for custom files. OCR does not read your file. Teachers can edit every extracted answer.','Diese Demo nutzt ein festes Bruch-Beispiel. OCR liest deine Datei nicht. Alle Antworten sind bearbeitbar.')}</p></details></aside></div>`;}
function status(){const e=state.active;if(!e)return empty(t('No exam sent yet','Noch keine Prüfung'),t('Add your pages to start.','Wähle deine Seiten.'),'upload',t('Upload exam','Prüfung senden'));const phases=[t('Pages received','Seiten erhalten'),t('Reading your answers','Antworten werden gelesen'),t('Teacher checks the text','Lehrkraft prüft den Text'),t('Suggested marks prepared','Notenvorschläge'),t('Teacher approves your feedback','Lehrkraft prüft Feedback'),t('Your result is ready','Dein Ergebnis ist da')];const st={scanning:1,verify:2,replacement:2,grading:3,grade:4,support:4,published:5}[e.status];return heading(e.status==='published'?t('Your result is ready!','Dein Ergebnis ist da!'):t('Your exam is in good hands.','Deine Prüfung ist in guten Händen.'),`${esc(e.name)} · ${t('Mathematics','Mathematik')}`)+`<div class="status-section">${stepper(e.status==='published'?2:1)}<section class="card"><div class="actions"><span class="icon-tile">${icon(e.status==='published'?'check':'clock')}</span><div><h2>${statusText(e.status)}</h2><p class="small">${t('Only your teacher-approved result will appear here.','Hier erscheint nur das freigegebene Ergebnis.')}</p></div></div><ul class="timeline">${phases.map((p,i)=>`<li class="${i<st?'complete':i===st?'now':''}"><span class="dot">${i<st?'✓':i+1}</span><div><h3>${p}</h3><p>${i<st?t('Complete','Erledigt'):i===st?t('Current step','Aktueller Schritt'):t('Coming next','Als Nächstes')}</p></div></li>`).join('')}</ul>${e.status==='replacement'?alert(esc(e.requestReason),'error') : ''}<div class="actions">${e.status==='published'?btn(t('See my result','Ergebnis ansehen'),'result','',`data-id="${e.id}"`):e.status==='replacement'?btn(t('Replace pages','Seiten ersetzen'),'upload'):btn(t('Back to home','Zur Startseite'),'nav','secondary','data-view="home"')}</div></section><p class="help-inline">${t('For the demo: switch to Reem’s teacher view to continue the review.','Für die Demo: Wechsle zur Lehreransicht, um fortzufahren.')}</p></div>`;}
function empty(title,sub,action,label){return `<section class="card empty"><span class="icon-tile">${icon('book')}</span><h2>${title}</h2><p>${sub}</p>${btn(label,action)}</section>`;}
function result(){let r=selectedResult===state.active?.id?M.visibleResult(state):state.history.find(x=>x.id===selectedResult);if(!r){if(state.active)return status();return results();}const current=r.id===state.active?.id;const score=current?M.total(r):r.score;return heading(esc(r.name),t('Your teacher has checked and approved this result.','Deine Lehrkraft hat dieses Ergebnis geprüft.'),btn(t('All results','Alle Ergebnisse'),'nav','secondary','data-view="results"'))+`<section class="result-hero"><div class="score-ring"><strong>${score}<span style="font-size:17px">/${current?10:r.max}</span></strong><small>${t('Teacher-approved','Freigegeben')}</small></div><div><div class="eyebrow">${t('ONE STEP FORWARD','EIN SCHRITT WEITER')}</div><h2>${t('Let’s build on what you know.','Nutze, was du schon kannst.')}</h2><p>${esc(r.feedback)}</p></div></section><div class="grid main-aside"><section class="card"><h2>${t('Your answers, explained','Deine Antworten, erklärt')}</h2>${r.marks.length===3?r.marks.map((m,i)=>`<div class="mark-breakdown"><div><h3>${i+1}. ${topic(i)}</h3><p class="small">${current?esc(r.comments[i]):esc(i===1?t('Correct comparison. Explain why using equal denominators.','Richtiger Vergleich. Begründe mit gleichen Nennern.'):t('Keep checking each step.','Prüfe jeden Schritt.'))}</p>${current?`<p class="small">${t('Your answer:','Deine Antwort:')} <strong>${esc(r.texts[i])}</strong></p>`:''}</div><strong>${m} / ${M.rubric[i].max}</strong></div>`).join(''):`<div class="mark-breakdown"><h3>${t('Multiplication','Multiplikation')}</h3><strong>9 / 10</strong></div>`}${btn(t('Ask my teacher','Lehrkraft fragen'),'ask-help','ghost')}</section><aside><section class="card feedback-card"><div class="eyebrow">${t('YOUR NEXT STEP','DEIN NÄCHSTER SCHRITT')}</div><h2>${t('From feedback to practice.','Vom Feedback zur Übung.')}</h2>${current?`<p>${esc(r.practice)}</p>${r.decision==='confirmed'?alert(t('Your teacher will help you with comparing fractions.','Deine Lehrkraft hilft dir beim Vergleichen von Brüchen.')):''}<div class="mini-note"><strong class="small">${t('We’ll check again','Wir schauen wieder nach')}</strong><p class="small">${esc(r.followup)}</p></div><div class="mt">${btn(t('Open my practice','Übung öffnen'),'practice')}</div>`:`<p>${t('Use your latest practice recommendation to keep growing.','Nutze deine nächste Übung zum Weiterlernen.')}</p>`}</section></aside></div>`;}
function results(){return heading(t('Your learning, one exam at a time.','Dein Lernen, Prüfung für Prüfung.'),t('Approved results and exams still being checked.','Freigegebene Ergebnisse und laufende Prüfungen.'))+`<section class="card">${resultTable()}</section>`;}
function chart(){const rs=allResults();const pts=rs.map((r,i)=>`${45+i*(400/Math.max(1,rs.length-1))},${145-r.score/r.max*110}`).join(' ');return `<svg class="chart" viewBox="0 0 490 185" role="img" aria-label="Exam progress: ${esc(rs.map(r=>r.name+' '+Math.round(r.score/r.max*100)+'%').join(', '))}"><path d="M35 35h425 M35 90h425 M35 145h425" stroke="#e4eadf"/><polyline points="${pts}" fill="none" stroke="#5c8657" stroke-width="3"/>${rs.map((r,i)=>{const x=45+i*(400/Math.max(1,rs.length-1));return `<circle cx="${x}" cy="${145-r.score/r.max*110}" r="5" fill="#245e50"/><text x="${x}" y="${128-r.score/r.max*110}" text-anchor="middle" fill="#254b3d" font-size="12">${Math.round(r.score/r.max*100)}%</text><text x="${x}" y="174" text-anchor="middle" fill="#637364" font-size="10">${esc(r.name)}</text>`}).join('')}</svg>`;}
function progress(){return heading(t('Look how far you’ve come.','Sieh, wie weit du gekommen bist.'),t('Your own progress. Your own pace.','Dein Fortschritt. Dein Tempo.'))+`<div class="grid two"><section class="card"><h2>${t('Mathematics over time','Mathematik im Zeitverlauf')}</h2><p class="small">${t('Teacher-approved exams only','Nur freigegebene Ergebnisse')}</p><div class="mt">${chart()}</div></section><section class="card"><h2>${t('Your topic steps','Deine Lernschritte')}</h2>${progressBars()}<p class="help">${t('Latest confirmed fractions assessment. Multiplication is shown separately in exam history.','Letzte freigegebene Bruchprüfung. Multiplikation steht im Verlauf.')}</p></section></div><section class="card mt">${resultTable()}</section>`;}
function messages(){return heading(t('A little note for you.','Eine Nachricht für dich.'),t('Feedback, practice and help from your teacher.','Feedback, Übungen und Hilfe.'),btn(t('Mark all as read','Alle als gelesen markieren'),'read-all','secondary'))+`<section class="card">${state.notifications.map(n=>`<article class="notification ${n.read?'':'unread'}"><span class="icon-tile">${icon(n.type==='result'?'book':'mail')}</span><div><strong>${t('From your teacher','Von deiner Lehrkraft')}</strong><p>${esc(state.lang==='de'?n.de||n.text:n.text)}</p></div><div class="actions">${btn(t('Open','Öffnen'),'open-note','secondary',`data-id="${n.id}"`)}</div></article>`).join('')||`<p>${t('You’re all caught up.','Du bist auf dem neuesten Stand.')}</p>`}</section>`;}
function practice(){const e=M.visibleResult(state);if(!e)return status();return heading(t('Make fractions make sense.','Brüche verstehen.'),t('Try this short activity. Your teacher will read your explanation.','Probiere diese Übung. Deine Lehrkraft liest deine Erklärung.'),btn(t('Back to result','Zurück zum Ergebnis'),'result','secondary',`data-id="${e.id}"`))+`<div class="grid two"><section class="card"><div class="eyebrow">EVIDENCE → PRACTICE</div><h2>${t('Compare one third and one fourth','Vergleiche ein Drittel und ein Viertel')}</h2><p>${esc(e.practice)}</p><div class="practice-visual mt"><label>1/3</label><div class="fraction-strip"><span>1/3</span><span></span><span></span></div><label>1/4</label><div class="fraction-strip"><span>1/4</span><span></span><span></span><span></span></div><p class="small">${t('Both strips are the same length. Which shaded part is larger?','Beide Streifen sind gleich lang. Welcher gefärbte Teil ist größer?')}</p></div></section><section class="card"><h2>${t('Tell me how you know','Erkläre, woher du es weißt')}</h2><label for="practice-answer" class="mt">${t('My explanation','Meine Erklärung')}</label><textarea id="practice-answer" rows="5" ${e.practiceStatus==='submitted'?'disabled':''}>${esc(e.practiceAnswer)}</textarea>${e.practiceStatus==='submitted'?alert(t('Sent! Your teacher will check your explanation.','Gesendet! Deine Lehrkraft prüft deine Erklärung.')):btn(t('Send my explanation','Erklärung senden'),'submit-practice','', 'style="margin-top:20px"')}${e.practiceReview?`<div class="mini-note"><h3>${t('Your teacher’s reply','Antwort deiner Lehrkraft')}</h3><p>${esc(e.practiceReview)}</p>${pill(e.practiceStatus==='resolved'?t('Follow-up complete','Nachkontrolle abgeschlossen'):t('Keep practising','Weiter üben'),'neutral')}</div>`:''}<p class="help">${t('Next check-in:','Nächster Termin:')} ${esc(e.followup)}</p></section></div>`;}
function teacherDashboard(){const e=state.active;return heading(t('A clearer picture of learning.','Lernen klarer verstehen.'),t('Welcome, Reem. Here’s where your attention can make a difference.','Willkommen, Reem. Hier kannst du heute helfen.'),btn(`${icon('file')} ${t('Open review queue','Prüfungen öffnen')}`,'nav','','data-view="queue"'),'GRADE 4 · MATHEMATICS')+`<div class="grid three stats"><div class="card stat"><span class="icon-tile">${icon('eye')}</span><div><strong>${e&&['verify','scanning','replacement'].includes(e.status)?1:0}</strong><p>${t('Awaiting text verification','Textprüfung offen')}</p></div></div><div class="card stat"><span class="icon-tile">${icon('edit')}</span><div><strong>${e&&['grading','grade'].includes(e.status)?1:0}</strong><p>${t('Awaiting grade review','Notenprüfung offen')}</p></div></div><div class="card stat"><span class="icon-tile">${icon('support')}</span><div><strong>${e?.status==='support'?1:0}</strong><p>${t('Support decision to review','Lernhilfe prüfen')}</p></div></div></div><div class="grid main-aside mt"><section class="card"><div class="review-label"><h2>${t('Next in your queue','Als Nächstes')}</h2>${pill(t('Teacher in control','Lehrkraft entscheidet'))}</div>${e?`<div class="exam-cell mb"><span class="exam-icon">${icon('file')}</span><div><h3>${esc(e.name)}</h3><p class="small">Ahmed · S-014 · ${new Date(e.date).toLocaleDateString()}</p></div></div>${pill(statusText(e.status),e.status==='published'?'':'pending')}<p class="mt small">${t('Review the original paper, confirm the text, then decide on marks and support.','Prüfe das Original, bestätige den Text und entscheide über Noten und Lernhilfe.')}</p><div class="mt">${btn(t('Open assessment','Prüfung öffnen'),'review')}</div>`:empty(t('Your queue is clear.','Keine offenen Prüfungen.'),t('A student upload will appear here. Switch to Ahmed to send the demonstration exam.','Eine gesendete Prüfung erscheint hier. Wechsle zu Ahmed und sende die Beispielprüfung.'),'switch',t('Switch to student','Zur Schüleransicht'))}</section><section class="card feedback-card"><div class="eyebrow">EVIDENCE-TO-PRACTICE</div><h2>${t('A signal is a starting point.','Ein Hinweis ist erst der Anfang.')}</h2><p>${t('Connect the original answer to a verified pattern, then choose a useful next step.','Verbinde die Antwort mit einem geprüften Muster und einer passenden Übung.')}</p><div class="mini-note"><h3>${t('Comparing fractions','Brüche vergleichen')}</h3><p class="small">${t('Ahmed’s earlier exam: 1/3 points. A new checked answer helps establish whether the difficulty repeats.','Ahmeds frühere Prüfung: 1/3 Punkte. Eine neue geprüfte Antwort zeigt, ob sich der Fehler wiederholt.')}</p></div>${btn(t('Review learning support','Lernhilfe ansehen'),'nav','ghost','data-view="support"')}</section></div>${state.teacherNotes.length?`<section class="card mt"><h2>${t('Questions from Ahmed','Fragen von Ahmed')}</h2>${state.teacherNotes.map(n=>`<div class="mini-note"><p>${esc(n.text)}</p><small>${new Date(n.date).toLocaleDateString()}</small></div>`).join('')}<div class="mt">${btn(t('Reply to Ahmed','Ahmed antworten'),'teacher-comment','secondary')}</div></section>`:''}<div class="section-head"><h2>${t('Students at a glance','Lernende im Überblick')}</h2>${btn(t('View students','Lernende ansehen'),'nav','ghost','data-view="students"')}</div><section class="card">${rosterTable()}</section>`;}
function queue(){const e=state.active;const matches=e&&('ahmed s-014 '+e.name).toLowerCase().includes(queueQuery.toLowerCase())&&(queueStatus==='all'||e.status===queueStatus);return heading(t('One thoughtful review at a time.','Eine sorgfältige Prüfung nach der anderen.'),t('Verified text first. Teacher-approved marks next.','Erst geprüfter Text. Dann freigegebene Noten.'))+`<section class="card"><div class="filters"><div class="field"><label for="queue-search">${t('Search student or exam','Schüler/in oder Prüfung suchen')}</label><input id="queue-search" type="search" value="${esc(queueQuery)}" placeholder="Ahmed, S-014..."></div><div class="field"><label for="queue-status">${t('Review status','Prüfstatus')}</label><select id="queue-status">${[['all',t('All statuses','Alle')],['verify',t('Text verification','Textprüfung')],['grade',t('Grade review','Notenprüfung')],['support',t('Support review','Lernhilfe')],['published',t('Published','Veröffentlicht')]].map(([v,l])=>`<option value="${v}" ${v===queueStatus?'selected':''}>${l}</option>`).join('')}</select></div><label class="check"><input type="checkbox" id="anonymous" ${state.anonymous?'checked':''}>${t('Anonymous marking','Anonym bewerten')}</label></div>${matches?`<div class="table-wrap"><table><thead><tr><th>${t('Student','Schüler/in')}</th><th>${t('Assessment','Prüfung')}</th><th>${t('Submitted','Gesendet')}</th><th>Status</th><th></th></tr></thead><tbody><tr><td><strong>${state.anonymous?'S-014':'Ahmed'}</strong><small>${t('Grade 4','Klasse 4')}</small></td><td>${esc(e.name)}<small>${e.lang==='de'?'Deutsch':'English'} · ${t('Mathematics','Mathematik')}</small></td><td>${new Date(e.date).toLocaleDateString()}</td><td>${pill(statusText(e.status),e.status==='published'?'':'pending')}</td><td>${btn(t('Open review','Öffnen'),'review','secondary')}</td></tr></tbody></table></div>`:empty(t('No matching assessments','Keine passenden Prüfungen'),e?t('Try another search or status.','Ändere Suche oder Status.'):t('Student submissions will appear here.','Gesendete Prüfungen erscheinen hier.'),'clear-filter',t('Clear filters','Filter löschen'))}<p class="help">${t('Anonymous marking hides names during review. Switch it off to locate a learner; support history uses their name for follow-up.','Anonyme Bewertung blendet Namen aus. Die Lernhistorie zeigt den Namen für die Nachbetreuung.')}</p></section>`;}
function demoSheet(){const e=state.active;return `<div class="sheet"><div class="sheet-head"><div class="question-num">LEARNINGBRIDGE · ${e.lang==='de'?'KLASSE 4':'GRADE 4'}</div><h3>${e.lang==='de'?'Brüche 2 — Mathematik':'Fractions 2 — Mathematics'}</h3><small>${t('Sample paper · fictional student answers','Beispielblatt · erfundene Antworten')}</small></div>${M.rubric.map((r,i)=>`<div class="question"><div class="question-num">${i+1} / ${r.max} ${t('points','Punkte')}</div><p style="color:var(--ink);font-size:13px">${esc(e.lang==='de'?r.de:r.en)}</p><div class="hand">${esc(i===2&&e.lang==='de'?'3/4 einer Pizza':r.answer)}</div></div>`).join('')}</div>`;}
function examPreview(){const files=state.active?.files||[];return `<div class="scan-scroll">${files[0]?.sample?demoSheet():`<div id="stored-preview"><p>${t('Loading uploaded paper…','Prüfung wird geladen…')}</p></div>`}</div><div class="actions mt">${files.map((f,i)=>btn(`${t('Page/file','Seite/Datei')} ${i+1}`,'preview-stored','secondary small',`data-index="${i}"`)).join('')}</div>`;}
function questionTabs(){return `<div class="question-tabs" aria-label="Question selection">${M.rubric.map((r,i)=>`<button class="question-tab ${q===i?'active':''}" data-action="question" data-index="${i}" aria-pressed="${q===i}">${t('Q','F')}${i+1} ${state.active.checked[i]?'✓':''}</button>`).join('')}</div>`;}
function review(){const e=state.active;if(!e)return queue();if(e.status==='scanning'||e.status==='grading')return heading(t('Preparing the next step','Nächster Schritt wird vorbereitet'),t('Simulated processing for this prototype.','Simulierte Verarbeitung für diesen Prototyp.'))+`<section class="card empty"><span class="spinner"></span><h2 class="mt">${statusText(e.status)}</h2><p>${t('You can leave this screen; the process will finish automatically.','Du kannst diese Ansicht verlassen. Der Vorgang wird automatisch abgeschlossen.')}</p></section>`;if(e.status==='replacement')return heading(t('Waiting for a clearer page','Warten auf eine deutlichere Seite'),esc(e.requestReason))+alert(t('The student has been notified. Switch to the student view to replace the page.','Die Nachricht wurde gesendet. Wechsle zur Schüleransicht, um die Seite zu ersetzen.'))+btn(t('Back to queue','Zurück zur Liste'),'nav','secondary','data-view="queue"');if(e.status==='grade')return grading();if(e.status==='support')return supportReview();if(e.status==='published')return publication();return heading(t('Make the text trustworthy.','Prüfe den erkannten Text.'),`${state.anonymous?'S-014':'Ahmed · S-014'} · ${esc(e.name)} · ${t('Text verification','Textprüfung')}`,btn(t('Back to queue','Zurück zur Liste'),'nav','secondary','data-view="queue"'))+`<div class="grid two"><section class="card"><div class="review-label"><h2>${t('Original paper','Originalprüfung')}</h2>${pill(e.lang==='de'?'Deutsch':'English','neutral')}</div>${examPreview()}</section><section class="card"><div class="review-label"><h2>${t('Extracted answers','Erkannte Antworten')}</h2>${pill(t('Simulated OCR','Simulierte OCR'),'pending')}</div>${questionTabs()}<h3>${topic(q)}</h3><p class="small">${esc(e.lang==='de'?M.rubric[q].de:M.rubric[q].en)}</p>${q===1?alert(t('Check the denominator carefully. The sample OCR read 1/9 where the paper says 1/4.','Prüfe den Nenner. Die Beispiel-OCR las 1/9 statt 1/4.'),'warning'):''}<div class="field mt"><label for="ocr-text">${t('Editable extracted answer','Bearbeitbare Antwort')}</label><textarea id="ocr-text" rows="3">${esc(e.texts[q])}</textarea><p class="help">${t('Saved as you type. Editing unchecks this answer.','Beim Tippen gespeichert. Änderungen heben die Prüfung auf.')}</p></div><label class="check"><input type="checkbox" id="answer-checked" ${e.checked[q]?'checked':''}>${t('I compared this answer with the original paper.','Ich habe diese Antwort mit dem Original verglichen.')}</label><div class="actions mt">${btn(t('Save correction','Korrektur speichern'),'save-ocr','secondary')}${btn(t('Next answer','Nächste Antwort'),'next-question','secondary')}</div><div class="review-controls"><span class="small">${e.checked.filter(Boolean).length}/3 ${t('answers checked','Antworten geprüft')}</span>${btn(t('Request clearer page','Deutlichere Seite anfordern'),'request-page','ghost')}</div><div class="mt">${btn(`${t('Confirm text & generate grades','Text bestätigen & Noten erzeugen')} ${icon('arrow')}`,'verify','',e.checked.every(Boolean)&&e.texts.every(x=>x.trim())?'':'disabled')}</div><p class="help">${t('Grading is locked until all three answers are checked.','Notenvorschläge erst nach Prüfung aller drei Antworten.')}</p></section></div>`;}
function grading(){const e=state.active;return heading(t('Your judgment makes it final.','Dein Urteil entscheidet.'),`${state.anonymous?'S-014':'Ahmed · S-014'} · ${esc(e.name)} · ${t('Verified text','Geprüfter Text')}`,btn(t('Reopen text verification','Textprüfung erneut öffnen'),'reopen','secondary'))+`<div class="grid main-aside"><section class="card">${questionTabs()}<div class="eyebrow">${t('QUESTION','FRAGE')} ${q+1} / 3</div><h2>${topic(q)}</h2><p>${esc(e.lang==='de'?M.rubric[q].de:M.rubric[q].en)}</p><div class="mini-note"><small>${t('VERIFIED STUDENT ANSWER','GEPRÜFTE ANTWORT')}</small><h3>${esc(e.texts[q])}</h3></div><div class="rubric"><strong>${t('Model answer & marking guide','Musterlösung & Bewertung')}</strong><p>${esc(e.modelAnswers?.[q]||M.rubric[q].model)}</p>${btn(t('Edit / import answer key','Musterlösung bearbeiten / importieren'),'answer-key','ghost small')}</div><div class="grade-grid"><div class="suggestion"><span class="small">${t('AI suggestion · simulated','KI-Vorschlag · simuliert')}</span><strong>${e.suggested[q]} / ${M.rubric[q].max}</strong><p class="small">${t('Fixed demo rubric; review against the verified answer.','Festes Demo-Raster; mit der geprüften Antwort vergleichen.')}</p></div><div class="grade-field"><label for="teacher-mark">${t('Your mark','Deine Bewertung')}</label><input id="teacher-mark" type="number" min="0" max="${M.rubric[q].max}" step="1" value="${e.marks[q]}" required><span> / ${M.rubric[q].max}</span></div></div><div class="field"><label for="question-feedback">${t('Feedback for this answer','Feedback zu dieser Antwort')}</label><textarea id="question-feedback">${esc(e.comments[q])}</textarea></div><div class="actions">${btn(t('Previous','Zurück'),'prev-question','secondary',q===0?'disabled':'')}${btn(t('Next question','Nächste Frage'),'next-question','secondary')}</div></section><aside><section class="card"><h2>${t('Marks at a glance','Bewertungen im Überblick')}</h2>${e.marks.map((m,i)=>`<div class="mark-breakdown"><span>${topic(i)}</span><strong data-score-index="${i}">${m} / ${M.rubric[i].max}</strong></div>`).join('')}<div class="mark-breakdown"><strong>${t('Total','Gesamt')}</strong><strong id="grade-total">${M.total(e)} / 10</strong></div><p class="help">${t('These marks are not visible to the student yet.','Diese Bewertungen sind noch nicht sichtbar.')}</p><div class="mt">${btn(t('Confirm marks & review support','Noten bestätigen & Lernhilfe prüfen'),'confirm-grades')}</div></section>${alert(t('Changes to verified text will clear grade and support approvals.','Textänderungen heben Noten- und Lernhilfe-Freigaben auf.'))}</aside></div>`;}
function supportReview(){const e=state.active;const gap=M.hasGap(e);return heading(t('Evidence. A decision. A next step.','Belege. Eine Entscheidung. Ein nächster Schritt.'),t('Review the learning pattern before releasing feedback to Ahmed.','Prüfe das Lernmuster vor der Freigabe für Ahmed.'),btn(t('Back to marks','Zurück zu den Noten'),'back-grade','secondary'))+`<div class="grid main-aside"><div><section class="card feedback-card"><div class="review-label"><div class="eyebrow no-margin">EVIDENCE-TO-PRACTICE CARD</div>${pill(gap?t('Suggested support','Lernhilfe vorgeschlagen'):t('No current repeated gap','Kein aktueller Wiederholungsfehler'),gap?'pending':'neutral')}</div><h2>${t('Explaining fraction comparisons','Bruchvergleiche erklären')}</h2><p>${gap?t('Two checked exams show difficulty with the comparison explanation. Review the evidence, not just the score.','In zwei geprüften Prüfungen fehlt die Erklärung. Prüfe die Belege, nicht nur die Note.'):t('The latest teacher mark shows full credit on comparison. The earlier difficulty alone is not enough evidence for a recurring current gap.','Die aktuelle Vergleichsaufgabe hat volle Punkte. Der frühere Fehler allein belegt kein wiederkehrendes Problem.')}</p><div class="evidence-line"><div class="score">1<span class="small">/3</span></div><div><h3>Fractions 1 · Q2</h3><small>04 NOV 2026 · ${t('Verified & approved','Geprüft & freigegeben')}</small><p>1/3 &gt; 1/4 · ${t('No explanation provided.','Keine Erklärung angegeben.')}</p></div></div><div class="evidence-line"><div class="score">${e.marks[1]}<span class="small">/3</span></div><div><h3>${esc(e.name)} · Q2</h3><small>${t('Teacher-confirmed mark','Bestätigte Bewertung')}</small><p>${esc(e.texts[1])}</p><p>${esc(e.comments[1])}</p></div></div><div class="help">${t('Illustrative trigger: repeated difficulty across two verified exams. This is not a diagnosis or a validated educational threshold.','Beispielregel: Schwierigkeit in zwei geprüften Prüfungen. Keine Diagnose oder validierte Schwelle.')}</div></section><section class="card mt"><h2>${t('Your support decision','Deine Entscheidung zur Lernhilfe')}</h2><div class="decision"><label><input type="radio" name="decision" value="confirmed" ${e.decision==='confirmed'?'checked':''}>${t('Confirm extra support','Zusätzliche Hilfe bestätigen')}</label><label><input type="radio" name="decision" value="dismissed" ${e.decision==='dismissed'?'checked':''}>${t('Dismiss suggestion','Vorschlag verwerfen')}</label></div><div class="field"><label for="reason">${t('Why this decision?','Warum diese Entscheidung?')}</label><textarea id="reason" placeholder="${t('Describe the evidence behind your decision…','Beschreibe die Belege…')}">${esc(e.reason)}</textarea></div><div class="field"><label for="feedback">${t('Personalised feedback · edit the suggestion','Persönliches Feedback · Vorschlag bearbeiten')}</label><textarea id="feedback" rows="3">${esc(e.feedback)}</textarea></div><div class="field"><label for="practice">${t('Practice recommendation','Übungsempfehlung')}</label><textarea id="practice">${esc(e.practice)}</textarea></div><div class="grid two"><div class="field"><label for="followup">${t('Follow-up date','Termin zur Nachkontrolle')}</label><input type="date" id="followup" value="${esc(e.followup)}"></div><div class="field"><label for="feedback-language">${t('Feedback language','Feedbacksprache')}</label><select id="feedback-language"><option>${e.lang==='de'?'Deutsch':'English'}</option></select><p class="help">${t('Matches the exam. No automatic translation of edited feedback.','Entspricht der Prüfung. Keine automatische Übersetzung.')}</p></div></div><label for="private-note">${t('Private teacher note (not sent)','Private Lehrernotiz (nicht gesendet)')}</label><textarea id="private-note">${esc(e.privateNote)}</textarea></section></div><aside><section class="publish-summary"><div class="eyebrow" style="color:#cbddc1">${t('READY TO RELEASE?','BEREIT ZUR FREIGABE?')}</div><div class="big-score">${M.total(e)}<span style="font-size:23px"> / 10</span></div><p>${t('Teacher-confirmed grade','Bestätigte Note')}</p><ul class="checklist">${[[true,t('Answers verified','Antworten geprüft')],[e.gradeConfirmed,t('Marks confirmed','Noten bestätigt')],[!!e.decision&&!!e.reason.trim(),t('Support decision explained','Lernhilfe begründet')],[!!e.feedback.trim(),t('Feedback reviewed','Feedback geprüft')],[!!e.practice.trim()&&!!e.followup,t('Practice & follow-up set','Übung & Termin gesetzt')]].map(([yes,label])=>`<li class="${yes?'':'no'}">${icon(yes?'check':'clock')}${label}</li>`).join('')}</ul>${btn(t('Preview student result','Schülerergebnis ansehen'),'preview-result','secondary')}${btn(t('Publish to Ahmed','Für Ahmed veröffentlichen'),'publish','',M.canPublish(e)?'':'disabled')}</section><p class="help-inline">${t('Changes save as you type. Publication sends a notification; nothing is released automatically.','Feld verlassen, um zu speichern. Erst die Freigabe sendet eine Nachricht.')}</p></aside></div>`;}
function publication(){const e=state.active;return heading(t('A clear next step, delivered.','Ein klarer nächster Schritt ist da.'),t('Ahmed can now see the approved result, feedback and practice.','Ahmed kann jetzt Ergebnis, Feedback und Übung sehen.'))+`<section class="card"><div class="result-hero"><span class="icon-tile">${icon('check')}</span><div><h2>${esc(e.name)} · ${M.total(e)} / 10</h2><p>${t('Published by Reem Ayman','Von Reem Ayman freigegeben')}</p></div></div><p>${esc(e.feedback)}</p><div class="actions mt">${btn(t('Switch to student result','Zum Schülerergebnis wechseln'),'student-result')}${btn(t('Student history & follow-up','Lernhistorie & Nachkontrolle'),'nav','secondary','data-view="students"')}${btn(t('Revise verified text','Geprüften Text ändern'),'reopen','ghost')}</div></section>`;}
const roster=[{name:'Ahmed',id:'S-014',score:'9 / 10',focus:'Comparing fractions',de:'Brüche vergleichen'},{name:'Lina',id:'S-021',score:'8 / 10',focus:'Explaining word problems',de:'Sachaufgaben erklären'},{name:'Omar',id:'S-008',score:'9 / 10',focus:'Multiplication fluency',de:'Sicher multiplizieren'}];
function rosterTable(){return `<div class="table-wrap"><table><thead><tr><th>${t('Student','Schüler/in')}</th><th>${t('Latest confirmed result','Letztes Ergebnis')}</th><th>${t('Learning focus','Lernschwerpunkt')}</th><th></th></tr></thead><tbody>${roster.map(r=>`<tr><td><strong>${r.name}</strong><small>${r.id} · ${t('Grade 4','Klasse 4')}</small></td><td>${r.name==='Ahmed'&&M.visibleResult(state)?M.total(state.active)+' / 10':r.score}</td><td>${state.lang==='de'?r.de:r.focus}</td><td>${btn(t('View history','Verlauf ansehen'),'profile','ghost',`data-name="${r.name}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function support(){const e=state.active;return heading(t('Notice patterns. Offer support.','Muster erkennen. Hilfe anbieten.'),t('Suggestions are starting points for your review, not labels for a child.','Vorschläge sind Hinweise zur Prüfung, keine Etiketten.'))+`<section class="card">${e&&['support','published'].includes(e.status)?`<div class="evidence-line"><span class="icon-tile">${icon('support')}</span><div><h2>Ahmed · ${t('Comparing fractions','Brüche vergleichen')}</h2><p>${t('Evidence across Fractions 1 and','Belege aus Fractions 1 und')} ${esc(e.name)}</p><div class="actions mt">${pill(e.decision?t(e.decision==='confirmed'?'Teacher confirmed':'Teacher dismissed',e.decision==='confirmed'?'Bestätigt':'Verworfen'):t('Needs teacher decision','Entscheidung offen'),e.decision?'':'pending')}${btn(t('Review evidence','Belege prüfen'),'review','secondary')}${btn(t('Open follow-up','Nachkontrolle öffnen'),'profile','ghost','data-name="Ahmed"')}</div></div></div>`:empty(t('More verified evidence is needed.','Weitere geprüfte Belege nötig.'),t('Complete OCR verification and grade confirmation to review the new learning pattern.','Prüfe den Text und bestätige die Noten, um das Muster zu prüfen.'),'review',t('Open review queue','Prüfungen öffnen'))}<div class="mini-note"><h3>${t('Context matters','Der Kontext zählt')}</h3><p class="small">${t('Attendance and missing homework may inform a conversation. They never automatically lower a grade or diagnose a difficulty here.','Anwesenheit und Hausaufgaben können ein Gespräch anregen. Sie senken hier nie automatisch die Note.')}</p></div></section>`;}
function students(){return heading(t('See the learner behind the marks.','Sieh den Menschen hinter den Noten.'),t('Confirmed results, learning evidence and thoughtful follow-up.','Bestätigte Ergebnisse, Lernbelege und Nachbetreuung.'),btn(`${icon('download')} ${t('Export reviewed results','Ergebnisse exportieren')}`,'export','secondary'))+`<section class="card">${rosterTable()}</section>${studentProfile()}`;}
function studentProfile(){const isAhmed=profileId==='Ahmed',e=isAhmed?M.visibleResult(state):null;return `<section class="card mt"><div class="review-label"><h2>${esc(profileId)} · ${t('Learning history','Lernhistorie')}</h2>${pill(t('Fictional demo record','Erfundener Demo-Datensatz'),'neutral')}</div>${isAhmed?`<div class="grid two"><div>${chart()}<h3>${t('Comparing fractions','Brüche vergleichen')}</h3><div class="evidence-line"><strong>Fractions 1</strong><p>1/3 · ${t('Missing explanation, verified answer.','Fehlende Erklärung, geprüfte Antwort.')}</p></div>${e?`<div class="evidence-line"><strong>${esc(e.name)}</strong><p>${e.marks[1]}/3 · ${esc(e.comments[1])}</p></div>`:''}</div><div><h3>${t('Support follow-up','Nachkontrolle')}</h3>${e?`<p>${esc(e.practice)}</p><p class="small mt">${t('Next check-in:','Nächster Termin:')} ${esc(e.followup)}</p><label class="mt" for="history-note">${t('Private teacher note','Private Lehrernotiz')}</label><textarea id="history-note">${esc(e.privateNote)}</textarea><div class="actions mt">${btn(t('Send a comment','Kommentar senden'),'teacher-comment','secondary')}${btn(t('Change check-in date','Termin ändern'),'change-date','ghost')}</div>`:`<p class="mt">${t('Complete and publish the assessment to open the Evidence-to-Practice follow-up.','Gib die Prüfung frei, um die Nachkontrolle zu öffnen.')}</p>`}</div></div>${e&&['submitted','resolved','continue'].includes(e.practiceStatus)?`<div class="mini-note mt"><h3>${t('Student practice response','Übungsantwort')}</h3><p>${esc(e.practiceAnswer)}</p>${pill(e.practiceStatus==='submitted'?t('Awaiting teacher review','Lehrerprüfung offen'):t('Teacher reviewed','Geprüft'),e.practiceStatus==='submitted'?'pending':'')}<div class="field mt"><label for="practice-review">${t('Your reply to the learner','Deine Antwort')}</label><textarea id="practice-review">${esc(e.practiceReview)}</textarea></div><div class="actions">${btn(t('Mark follow-up complete','Nachkontrolle abschließen'),'review-practice','','data-outcome="resolved"')}${btn(t('Continue practice','Weiter üben'),'review-practice','secondary','data-outcome="continue"')}</div></div>`:''}`:`<p>${t('Historical demonstration record. This student has no pending assessment in the current workflow.','Historischer Beispieldatensatz. Aktuell keine offene Prüfung.')}</p><div class="grid two mt"><div class="mini-note"><h3>${profileId==='Lina'?'8 / 10':'9 / 10'}</h3><p>${profileId==='Lina'?t('Word problems · 8 November','Sachaufgaben · 8. November'):t('Multiplication · 9 November','Multiplikation · 9. November')}</p></div><div class="mini-note"><h3>${t('Teacher feedback','Lehrerfeedback')}</h3><p>${profileId==='Lina'?t('Show the steps in your word-problem explanation.','Zeige die Schritte in deiner Erklärung.'):t('Your multiplication checks are becoming more consistent.','Du prüfst deine Multiplikation zunehmend sicher.')}</p></div></div>`}</section>`;}
function activity(){return heading(t('A traceable review.','Eine nachvollziehbare Prüfung.'),t('Changes and decisions recorded during this demonstration.','Änderungen und Entscheidungen in dieser Demo.'))+`<section class="card">${state.audit.map(a=>`<div class="audit"><strong>${esc(a.text)}</strong><small>${new Date(a.at).toLocaleString()}</small></div>`).join('')||`<p>${t('No review actions yet.','Noch keine Prüfaktionen.')}</p>`}</section>`;}
function render(){if(!state.role){app.innerHTML=entry();return;}let content;try{const student={home:studentHome,upload,status,result,results,progress,messages,practice};const teacher={dashboard:teacherDashboard,queue,review,support,students,activity};const pages=state.role==='student'?student:teacher;content=(pages[view]||pages[state.role==='student'?'home':'dashboard'])();}catch(err){content=alert(esc(err.message),'error')+btn(t('Back to home','Zur Startseite'),'home');}app.innerHTML=shell(content);loadStoredPreview();scheduleProcessing();}
function scheduleProcessing(){clearTimeout(processTimer);if(state.active?.status==='scanning'){processTimer=setTimeout(()=>{M.finishScan(state);save();render();},1600);}else if(state.active?.status==='grading'){processTimer=setTimeout(()=>{M.finishGrade(state);save();render();},1600);}}
function openModal(title,html,actions=''){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close">×</button></div>${html}<div class="actions">${actions||btn(t('Close','Schließen'),'close','secondary')}</div>`;modal.showModal();}
function guide(){openModal(t('A complete journey in a few minutes','Ein ganzer Ablauf in wenigen Minuten'),`<ol style="padding-left:22px;line-height:1.9;font-size:14px"><li>${t('Student: Upload exam → Use a sample exam → check readability → Send.','Schüler: Prüfung senden → Beispielprüfung → Lesbarkeit bestätigen → Senden.')}</li><li>${t('Switch role to Reem → Review queue → Open review.','Zu Reem wechseln → Prüfungen → Öffnen.')}</li><li>${t('Check all 3 answers. Correct Q2 from 1/9 to 1/4. Confirm text.','Alle 3 Antworten prüfen. In F2 1/9 zu 1/4 korrigieren. Text bestätigen.')}</li><li>${t('Review or change marks and comments; confirm grades.','Noten und Kommentare prüfen oder ändern; bestätigen.')}</li><li>${t('Review evidence, confirm or dismiss support, give a reason, set a follow-up date, preview and publish.','Belege prüfen, Lernhilfe bestätigen oder verwerfen, begründen, Termin setzen, ansehen und freigeben.')}</li><li>${t('Student: open the notification → result → practice → send explanation. Teacher: Students → review practice.','Schüler: Nachricht → Ergebnis → Übung → Erklärung senden. Lehrkraft: Lernende → Übung prüfen.')}</li></ol>${alert(t('The same browser stores both roles. No real AI, email, school accounts or shared server records are used. Reloading keeps your demo state; Reset demo clears it.','Beide Ansichten nutzen denselben Browser. Keine echte KI, E-Mail oder Schul-Datenbank. Neuladen behält den Stand; Zurücksetzen löscht ihn.'))}`);}
function db(){return new Promise((resolve,reject)=>{if(fileDB)return resolve(fileDB);const req=indexedDB.open('learningbridge-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>{fileDB=req.result;resolve(fileDB)};req.onerror=()=>reject(Error('File storage is unavailable in this browser.'));});}
async function storeBlob(id,file){const d=await db();return new Promise((res,rej)=>{const tx=d.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=res;tx.onerror=()=>rej(Error('Could not save this file. Try a smaller file.'));});}
async function getBlob(id){const d=await db();return new Promise((res,rej)=>{const r=d.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=rej;});}
async function clearFiles(){try{const d=await db();d.transaction('files','readwrite').objectStore('files').clear();}catch{}}
async function addFiles(files){uploadError='';for(const f of files){if(!['image/png','image/jpeg','application/pdf'].includes(f.type)){uploadError=t('Choose a PNG, JPG or PDF file.','Wähle PNG, JPG oder PDF.');continue;}if(f.size>5*1024*1024||f.size===0){uploadError=t('Choose a non-empty file smaller than 5 MB.','Wähle eine nicht leere Datei unter 5 MB.');continue;}if(draft.length>=4){uploadError=t('You can add up to 4 files. Remove one to add another.','Höchstens 4 Dateien. Entferne eine, um eine neue hinzuzufügen.');break;}const id='file-'+Date.now()+'-'+Math.random().toString(36).slice(2);try{await storeBlob(id,f);draft.push({id,name:f.name,type:f.type,size:f.size,sample:false});}catch(err){uploadError=err.message;}}render();}
async function showFile(f,lang=examLang){if(f.sample){const old=state.active;state.active={lang};openModal(esc(f.name),demoSheet());state.active=old;return;}const blob=await getBlob(f.id);if(!blob){openModal(t('File unavailable','Datei nicht verfügbar'),`<p>${t('Please replace this file. Browser storage may have been cleared.','Bitte ersetze diese Datei. Der Browserspeicher wurde möglicherweise gelöscht.')}</p>`);return;}const url=URL.createObjectURL(blob);openModal(esc(f.name),f.type==='application/pdf'?`<iframe title="Exam preview" src="${url}" style="width:100%;height:55vh;border:0"></iframe><a href="${url}" download="${esc(f.name)}">${t('Download PDF','PDF herunterladen')}</a>`:`<img src="${url}" alt="Uploaded exam page" style="max-width:100%;max-height:65vh;object-fit:contain">`);modal.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
async function loadStoredPreview(){const target=$('#stored-preview'),f=state.active?.files?.[0];if(!target||!f)return;try{const blob=await getBlob(f.id);if(!blob){target.innerHTML=alert(t('The stored paper is missing. Request a replacement before approving text.','Das gespeicherte Blatt fehlt. Bitte Ersatz anfordern.'),'error');return;}const url=URL.createObjectURL(blob);if(!target.isConnected){URL.revokeObjectURL(url);return;}target.innerHTML=f.type==='application/pdf'?`<iframe title="Original uploaded exam" src="${url}"></iframe>`:`<img alt="Original uploaded exam" src="${url}">`;setTimeout(()=>URL.revokeObjectURL(url),60000);}catch{target.innerHTML=alert(t('Cannot load the file. Request a clearer page to recover.','Datei nicht ladbar. Bitte Ersatz anfordern.'),'error');}}
function localDate(){return new Date().toISOString().slice(0,10);}
function updatePublishButton(){const e=state.active,b=$('[data-action="publish"]');if(b)b.disabled=!M.canPublish(e);const checks=$('.checklist');if(checks){const flags=[true,e.gradeConfirmed,!!e.decision&&!!e.reason.trim(),!!e.feedback.trim(),!!e.practice.trim()&&!!e.followup];checks.querySelectorAll('li').forEach((li,i)=>{li.classList.toggle('no',!flags[i]);li.querySelector('svg').outerHTML=icon(flags[i]?'check':'clock');});}}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function change(e){const el=e.target,id=el.id,a=state.active;if(id==='language'){state.lang=el.value;document.documentElement.lang=state.lang;save();render();return;}if(id==='exam-language'){examLang=el.value;render();return;}if(id==='files'||id==='camera'){addFiles([...el.files]);return;}if(id==='fail-upload'){uploadFail=el.checked;return;}if(id==='queue-search'){queueQuery=el.value;render();return;}if(id==='queue-status'){queueStatus=el.value;render();return;}if(id==='anonymous'){state.anonymous=el.checked;save();render();return;}if(id==='key-file'){const f=el.files[0];if(f&&f.size<100000){f.text().then(v=>{$('#key-text').value=v;});}else toast(t('Use a text file smaller than 100 KB.','Nutze eine Textdatei unter 100 KB.'));return;}if(!a)return;if(id==='answer-checked'){if(!a.texts[q].trim()){el.checked=false;toast(t('Enter an answer before marking it checked.','Gib zuerst eine Antwort ein.'));return;}a.checked[q]=el.checked;save();render();return;}if(el.name==='decision'){a.decision=el.value;M.record(state,'Support suggestion '+el.value+' by teacher');save();render();return;}}
function input(e){const el=e.target,a=state.active;if(!a)return;const map={'reason':'reason','feedback':'feedback','practice':'practice','followup':'followup','private-note':'privateNote','history-note':'privateNote','practice-answer':'practiceAnswer','practice-review':'practiceReview'};if(map[el.id]){a[map[el.id]]=el.value;save();updatePublishButton();return;}if(el.id==='ocr-text'){M.editText(state,q,el.value);const c=$('#answer-checked');if(c)c.checked=false;const b=$('[data-action="verify"]');if(b)b.disabled=true;save();}if(el.id==='teacher-mark'){a.marks[q]=el.value===''?NaN:Number(el.value);const total=$('#grade-total');if(total)total.textContent=(Number.isFinite(M.total(a))?M.total(a):'—')+' / 10';const row=$('[data-score-index="'+q+'"]');if(row)row.textContent=(Number.isFinite(a.marks[q])?a.marks[q]:'—')+' / '+M.rubric[q].max;save();el.setCustomValidity(Number.isInteger(a.marks[q])&&a.marks[q]>=0&&a.marks[q]<=M.rubric[q].max?'':t('Enter a whole number within the shown range.','Gib eine ganze Zahl im Bereich ein.'));}if(el.id==='question-feedback'){a.comments[q]=el.value;save();}}
document.addEventListener('change',change);document.addEventListener('input',input);
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.add('drag')}});
document.addEventListener('dragleave',e=>{if(e.target.closest('#dropzone'))$('#dropzone')?.classList.remove('drag')});
document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();addFiles([...e.dataTransfer.files]);}});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,e=state.active;try{switch(action){
case 'nav':if(el.dataset.view==='upload'&&e?.status==='replacement')examLang=e.lang;go(el.dataset.view);break;
case 'home':go(state.role==='teacher'?'dashboard':'home');break;
case 'role':state.role=el.dataset.role;save();go(state.role==='teacher'?'dashboard':'home');break;
case 'switch':state.role=null;save();render();break;
case 'upload':if(e?.status==='replacement')examLang=e.lang;go('upload');break;
case 'status':go('status');break;
case 'result':selectedResult=el.dataset.id;go('result');break;
case 'review':q=0;go('review');break;
case 'practice':go('practice');break;
case 'profile':profileId=el.dataset.name;go('students');break;
case 'question':if($('#teacher-mark')&&!$('#teacher-mark').reportValidity())return;q=Number(el.dataset.index);render();break;
case 'next-question':if($('#teacher-mark')&&!$('#teacher-mark').reportValidity())return;q=(q+1)%3;render();break;
case 'prev-question':q=Math.max(0,q-1);render();break;
case 'answer-key':openModal(t('Answer key for this question','Musterlösung für diese Frage'),`<label for="key-text">${t('Model answer and rubric','Musterlösung und Bewertung')}</label><textarea id="key-text" rows="5">${esc(e.modelAnswers?.[q]||M.rubric[q].model)}</textarea><label for="key-file" class="mt">${t('Import a plain-text answer key (.txt)','Textdatei importieren (.txt)')}</label><input id="key-file" type="file" accept="text/plain,.txt"><p class="help">${t('Import changes the displayed marking guide, not the simulated grade engine. Review marks yourself.','Import ändert die Musterlösung, nicht die simulierten Noten. Prüfe die Bewertung selbst.')}</p>`,btn(t('Cancel','Abbrechen'),'close','secondary')+btn(t('Save answer key','Musterlösung speichern'),'save-key'));break;
case 'save-key':if(!$('#key-text').value.trim())throw Error(t('Enter an answer key.','Gib eine Musterlösung ein.'));e.modelAnswers||=M.rubric.map(r=>r.model);e.modelAnswers[q]=$('#key-text').value;M.record(state,'Teacher updated the question '+(q+1)+' marking guide');save();modal.close();render();break;
case 'clear-filter':queueQuery='';queueStatus='all';render();break;
case 'close':modal.close();break;
case 'guide':guide();break;
case 'reset':openModal(t('Start a fresh demonstration?','Neue Demo starten?'),`<p>${t('This clears this browser’s uploads, review decisions and messages. The original example history will return.','Dies löscht Uploads, Entscheidungen und Nachrichten in diesem Browser.')}</p>`,btn(t('Keep my work','Behalten'),'close','secondary')+btn(t('Reset demo','Zurücksetzen'),'confirm-reset','danger'));break;
case 'confirm-reset':await clearFiles();state=M.initial();draft=[];selectedResult=null;q=0;uploadError='';uploadFail=false;save();modal.close();go('home');toast(t('Demo reset.','Demo zurückgesetzt.'));break;
case 'sample':if(draft.length>=4){uploadError=t('Remove a file before adding another.','Entferne zuerst eine Datei.');render();break;}draft.push({id:'sample-'+Date.now(),name:examLang==='de'?'Brueche-2-Beispiel.svg':'Fractions-2-sample.svg',size:5800,type:'image/svg+xml',sample:true});uploadError='';render();toast(t('Sample exam added. Check it before sending.','Beispiel hinzugefügt. Bitte vor dem Senden prüfen.'));break;
case 'preview-draft':await showFile(draft[Number(el.dataset.index)]);break;
case 'preview-stored':await showFile(e.files[Number(el.dataset.index)],e.lang);break;
case 'remove-file':draft.splice(Number(el.dataset.index),1);render();break;
case 'move-file':{const i=Number(el.dataset.index);[draft[i-1],draft[i]]=[draft[i],draft[i-1]];render();break;}
case 'send':if(!draft.length){uploadError=t('Add at least one exam page first.','Füge zuerst eine Prüfungsseite hinzu.');render();break;}if(!$('#readable')?.checked){uploadError=t('Please check the readability confirmation before sending.','Bitte bestätige die Lesbarkeit vor dem Senden.');render();break;}if(uploadFail){uploadFail=false;uploadError=t('Connection interrupted. Your pages are safe here. Check the box and send again.','Verbindung unterbrochen. Deine Seiten bleiben hier. Bestätige erneut und sende.');render();break;}if(e?.status==='replacement')M.replacePages(state,[...draft]);else{if(e?.status==='published'){state.history.push({...e,score:M.total(e),max:10});}M.newExam(state,{lang:examLang,files:[...draft]});}draft=[];uploadError='';save();go('status');toast(t('Exam received.','Prüfung erhalten.'));break;
case 'save-ocr':save();render();toast(t('Correction saved. Mark this answer checked after comparing it.','Korrektur gespeichert. Bestätige anschließend die Prüfung.'));break;
case 'verify':for(const file of e.files){if(!file.sample&&!(await getBlob(file.id)))throw Error(t('Original paper missing. Request a replacement first.','Original fehlt. Bitte zuerst Ersatz anfordern.'));}M.verify(state);save();render();break;
case 'request-page':openModal(t('Request a clearer page','Deutlichere Seite anfordern'),`<label for="request-reason">${t('Tell Ahmed what to replace','Was soll Ahmed ersetzen?')}</label><textarea id="request-reason" placeholder="${t('Page 1 is blurry. Please take another photo.','Seite 1 ist unscharf. Bitte neu fotografieren.')}"></textarea>`,btn(t('Cancel','Abbrechen'),'close','secondary')+btn(t('Send request','Anfrage senden'),'send-request'));break;
case 'send-request':M.requestPage(state,$('#request-reason').value);save();modal.close();render();toast(t('Replacement request sent.','Anfrage gesendet.'));break;
case 'confirm-grades':if($('#teacher-mark')&&!$('#teacher-mark').reportValidity())return;M.confirmGrades(state);save();render();break;
case 'back-grade':e.status='grade';e.gradeConfirmed=false;e.decision=null;M.record(state,'Marks reopened; support decision reset');save();render();break;
case 'reopen':openModal(t('Reopen text verification?','Textprüfung erneut öffnen?'),`<p>${t('All answers must be checked again. Current grade and support approvals will be cleared. Published results will be hidden until you approve them again.','Alle Antworten müssen erneut geprüft werden. Noten- und Lernhilfe-Freigaben werden aufgehoben; Ergebnisse bleiben bis zur erneuten Freigabe verborgen.')}</p>`,btn(t('Cancel','Abbrechen'),'close','secondary')+btn(t('Reopen verification','Erneut öffnen'),'confirm-reopen'));break;
case 'confirm-reopen':M.revise(state);q=0;save();modal.close();go('review');break;
case 'preview-result':openModal(t('Student preview · not published','Schülervorschau · nicht veröffentlicht'),`<div class="result-hero"><div class="score-ring"><strong>${M.total(e)}/10</strong></div><div><h3>${esc(e.name)}</h3><p>${esc(e.feedback)}</p></div></div><h3>${t('Your next practice','Deine nächste Übung')}</h3><p>${esc(e.practice)}</p>${e.decision==='confirmed'?alert(t('Your teacher will help you with comparing fractions.','Deine Lehrkraft hilft dir beim Vergleichen von Brüchen.')):''}<p>${t('Next check-in:','Nächster Termin:')} ${esc(e.followup||'—')}</p>`);break;
case 'publish':openModal(t('Publish this result to Ahmed?','Dieses Ergebnis freigeben?'),`<p>${t('This will release the teacher-confirmed grade, feedback and practice, and send a student notification. Private notes are not included.','Note, Feedback und Übung werden freigegeben. Private Notizen bleiben verborgen.')}</p><h3>${esc(e.name)} · ${M.total(e)} / 10</h3>`,btn(t('Keep reviewing','Weiter prüfen'),'close','secondary')+btn(t('Confirm publication','Freigabe bestätigen'),'confirm-publish'));break;
case 'confirm-publish':M.publish(state);save();modal.close();render();toast(t('Published. Ahmed has a new notification.','Freigegeben. Ahmed hat eine neue Nachricht.'));break;
case 'student-result':state.role='student';selectedResult=e.id;save();go('result');break;
case 'read-all':state.notifications.forEach(n=>n.read=true);save();render();toast(t('All messages marked as read.','Alle als gelesen markiert.'));break;
case 'open-note':{const n=state.notifications.find(n=>n.id===el.dataset.id);n.read=true;save();if(n.type==='replace')go('upload');else if(n.type==='practice')go('practice');else if(n.type==='result'){selectedResult=n.target;go('result');}else{openModal(t('From your teacher','Von deiner Lehrkraft'),`<p>${esc(state.lang==='de'?n.de||n.text:n.text)}</p>`);render();}break;}
case 'ask-help':openModal(t('Ask your teacher','Frage deine Lehrkraft'),`<label for="help-message">${t('What would you like help with?','Wobei brauchst du Hilfe?')}</label><textarea id="help-message"></textarea>`,btn(t('Cancel','Abbrechen'),'close','secondary')+btn(t('Send question','Frage senden'),'send-help'));break;
case 'send-help':{const text=$('#help-message').value.trim();if(!text)throw Error(t('Write your question first.','Schreibe zuerst deine Frage.'));state.teacherNotes.unshift({text,date:new Date().toISOString()});M.record(state,'Ahmed asked for help: '+text);save();modal.close();toast(t('Your question was sent to your teacher.','Deine Frage wurde gesendet.'));break;}
case 'submit-practice':if(!e.practiceAnswer.trim())throw Error(t('Write your explanation before sending.','Schreibe deine Erklärung vor dem Senden.'));e.practiceStatus='submitted';M.record(state,'Ahmed submitted a practice explanation');save();render();toast(t('Your teacher will review your explanation.','Deine Lehrkraft wird deine Erklärung prüfen.'));break;
case 'review-practice':if(!e.practiceReview.trim())throw Error(t('Add feedback before completing the follow-up.','Füge vor dem Abschluss Feedback hinzu.'));e.practiceStatus=el.dataset.outcome;state.notifications.unshift({id:'practice-'+Date.now(),text:e.practiceReview,de:e.practiceReview,type:'practice',read:false,target:e.id});M.record(state,'Teacher reviewed practice: '+el.dataset.outcome);save();render();toast(t('Practice feedback sent.','Übungsfeedback gesendet.'));break;
case 'teacher-comment':openModal(t('Send a comment to Ahmed','Kommentar an Ahmed'),`<label for="teacher-message">${t('Message','Nachricht')}</label><textarea id="teacher-message"></textarea>`,btn(t('Cancel','Abbrechen'),'close','secondary')+btn(t('Send comment','Kommentar senden'),'send-comment'));break;
case 'send-comment':{const text=$('#teacher-message').value.trim();if(!text)throw Error(t('Write a message first.','Schreibe zuerst eine Nachricht.'));state.notifications.unshift({id:'comment-'+Date.now(),text,de:text,type:'comment',read:false});M.record(state,'Teacher sent a comment');save();modal.close();toast(t('Comment sent to Ahmed.','Kommentar gesendet.'));break;}
case 'change-date':openModal(t('Choose the next check-in','Nächsten Termin wählen'),`<label for="new-date">${t('Follow-up date','Termin')}</label><input id="new-date" type="date" value="${esc(e.followup)}">`,btn(t('Cancel','Abbrechen'),'close','secondary')+btn(t('Save date','Termin speichern'),'save-date'));break;
case 'save-date':if(!$('#new-date').value)throw Error(t('Choose a date.','Wähle ein Datum.'));e.followup=$('#new-date').value;M.record(state,'Follow-up date changed to '+e.followup);save();modal.close();render();break;
case 'export':{const safe=v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const rows=[['Student','Exam','Score','Maximum','Status'],...allResults().map(r=>['Ahmed',r.name,r.score,r.max,'Teacher approved'])];download('LearningBridge-reviewed-results.csv',rows.map(r=>r.map(safe).join(',')).join('\n'),'text/csv');toast(t('Reviewed results exported.','Ergebnisse exportiert.'));break;}
default:throw Error('Unknown action: '+action);
}}catch(err){toast(err.message);}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==view){view=next;render();}});
window.addEventListener('storage',ev=>{if(ev.key===M.KEY){try{state=JSON.parse(ev.newValue)||M.initial();render();}catch{}}});
document.documentElement.lang=state.lang;render();
